import {BrowserClient,BrowserEnrollmentKey,BrowserEnrollmentStore,BrowserSdkClient,browserOperationKinds,sdkId} from '/sdk/browser.js';
const trace=[],begin=BrowserClient.prototype.begin;
BrowserClient.prototype.begin=function(...args){trace.push({request:args[0],operation:args[2]?.operation_id});return begin.apply(this,args);};
const assert=(value,label)=>{if(!value)throw Error(label);};
const decode=s=>Uint8Array.from(atob(s.replaceAll('-','+').replaceAll('_','/')),v=>v.charCodeAt(0));
async function post(path,value){const response=await fetch(path,{method:'POST',headers:{'Content-Type':'application/json'},credentials:'omit',body:JSON.stringify(value)});assert(response.ok,'owned fixture backend');return response.json();}
globalThis.runBrowserFixture=async cfg=>{try{
 const key=await crypto.subtle.importKey('raw',decode(cfg.server_public_raw),{name:'Ed25519'},true,['verify']),server={key,keyId:cfg.server_keyid,algorithm:'EdDSA',notBefore:cfg.server_not_before,expiresAt:cfg.server_expires_at},pins=[{algorithm:'sha-256',value:decode(cfg.certificate_sha256)}],identities=[cfg.identity_id,cfg.recipient_id],vault=new BrowserEnrollmentStore('connect-receipts-browser'),profiles=[],now=Math.floor(Date.now()/1000),options={timeoutMs:5000};
 for(let actor=0;actor<2;actor++){
  const device='receipt-device-'+cfg.suffix+'-'+actor,byPath={};
  for(const purpose of ['webtransport','wss-webrtc','application']){
   const name=cfg.suffix+'-'+actor+'-'+purpose,key=await BrowserEnrollmentKey.generate('EdDSA'),read=purpose==='application',transport=read?'wss-webrtc':purpose;
   await vault.prepare(name,cfg.api_origin,{operation_id:'approve-'+name,completion_operation_id:'claim-'+name,identity_id:identities[actor],device:{id:device,kind:'browser',platform:'owned-Chrome'},key_id:'key-'+name,algorithm:key.algorithm,public_key:key.publicKey,transport,endpoint_address:location.origin+'/device/'+name,capabilities:read?['control']:['control','data'],browser_origin:location.origin,operations:read?['history']:['conversation.get','conversation.subscribe','create','history','operation.get','send'],recipients:identities,credential_expires_at:now+300,challenge_expires_at:now+120},key);
   const offer=(await post('/receipts-approve',await vault.request(name))).result.Ok;await (await vault.acceptOffer(name,offer)).claim();
   if(!read)byPath[purpose]={name,contact:{url:purpose==='webtransport'?cfg.wt_url:cfg.wss_url,server,...(purpose==='webtransport'?{serverCertificateHashes:pins}:{})}};
   else profiles[actor]={device,byPath,application:{name,url:cfg.api_origin}};
  }
 }
 const result={passed:true,direct_wt:0,bounded_wss_fallback:0,queued_journal:0,delivered_client_reported:0,recipient_read:0,reconnected_read:0,original_operation_recovered:0,http_revoked_control_current:0},saved=[];
 for(const path of ['webtransport','wss-webrtc']){
  const clients=[],resolutions=[[],[]],suffix=cfg.suffix+'-'+path;
  try{
   for(let actor=0;actor<2;actor++){const resolve=vault.resolveProfiles(profiles[actor].byPath);clients.push(await BrowserSdkClient.connect({tenantId:'tnt_default',identityId:identities[actor],deviceId:profiles[actor].device,endpoints:{webtransport:path==='webtransport'?cfg.wt_url:cfg.unreachable_wt_url,'wss-webrtc':cfg.wss_url},timeoutMs:5000,attemptTimeoutMs:350,resolveEnrollment:context=>{resolutions[actor].push(context.transport);return resolve(context);},resolveApplicationRead:vault.resolveApplicationReads(profiles[actor].application)}));}
   const [caller,callee]=clients;assert(clients.every(c=>c.transport.selectedTransport===path),'same receipt workflow on selected transport');assert(resolutions.every(v=>JSON.stringify(v)===JSON.stringify(path==='webtransport'?['webtransport']:['webtransport','wss-webrtc'])),'separate transport-bound control enrollment');result[path==='webtransport'?'direct_wt':'bounded_wss_fallback']++;
   const createId=sdkId('receipt-room-'+suffix);sessionStorage.setItem('receipt-room-'+suffix,JSON.stringify({operationId:createId,input:{policy:'persistent',participants:[identities[1]]}}));const opened=await caller.conversations.create({policy:'persistent',participants:[sdkId(identities[1])]},{...options,operationId:createId}),room=(await opened.wait(options)).value,target=await room.participants.byIdentity(sdkId(identities[1]),options),other=callee.conversations.byId(room.id),events=other.events({},options);
   try{
    await events.ready();const input={messageId:sdkId('typed-message-caller-'+suffix),to:{first:target.id,rest:[]},text:'owned receipt '+path},operationId=sdkId('receipt-send-'+suffix);sessionStorage.setItem('receipt-send-'+suffix,JSON.stringify({conversationId:room.id,input,operationId}));const send=await room.send(input,{...options,operationId});sessionStorage.setItem('receipt-reference-'+suffix,JSON.stringify(send.referenceJson()));const acceptance=(await send.wait(options)).value;assert(acceptance.boundary==='local-mutation','acceptance remains distinct from delivery');
    const queued=await room.receipts(input.messageId,options);assert(queued.length===1&&queued[0].state==='queued'&&queued[0].provenance==='journal'&&queued[0].participantId===target.id,'current queued journal fact');result.queued_journal++;
    let received=false;for(let n=0;n<16;n++){const fact=(await events.next()).value;if(fact.data?.kind==='message'&&fact.data.data.id===input.messageId){assert(fact.data.data.body===input.text,'recipient got exact journal Message');received=true;break;}}assert(received,'recipient journal fact before synthetic report');
    const report={op:'message_receipt',request_id:'typed-receipt-'+suffix,conversation_id:room.id,message_id:input.messageId,state:'delivered'};sessionStorage.setItem('receipt-report-'+suffix,JSON.stringify(report));await post('/typed-receipt',report);
    const valid=facts=>facts.length===1&&facts[0].participantId===target.id&&facts[0].membershipEpoch===1&&facts[0].channel==='native'&&facts[0].state==='delivered'&&facts[0].provenance==='client_reported'&&Object.isFrozen(facts)&&Object.isFrozen(facts[0]);assert(valid(await room.receipts(input.messageId,options)),'attributed sender observation');result.delivered_client_reported++;assert(valid(await other.receipts(input.messageId,options)),'original recipient observation');result.recipient_read++;
    await caller.reconnect({preferredTransport:path});assert(valid(await room.receipts(input.messageId,options)),'current application read after explicit reconnect');result.reconnected_read++;assert((await caller.operations.restore(JSON.parse(sessionStorage.getItem('receipt-reference-'+suffix)),browserOperationKinds.messageSend).wait(options)).value.messageId===input.messageId,'original message recovery never resubmits');result.original_operation_recovered++;saved.push({conversationId:room.id,messageId:input.messageId});
   }finally{await events.close();}
  }finally{for(const client of clients)client.close();}
 }
 const session=await vault.load(profiles[0].application.name),issued=await session.claim(),read=session.applicationReadOptions(issued,cfg.api_origin),client=await BrowserSdkClient.connect({tenantId:'tnt_default',identityId:identities[0],deviceId:profiles[0].device,endpoints:{webtransport:cfg.wt_url},preferredTransport:'webtransport',timeoutMs:5000,resolveEnrollment:vault.resolveProfiles(profiles[0].byPath),resolveApplicationRead:async()=>read});
 try{const room=client.conversations.byId(saved[0].conversationId),epoch=client.transport.physicalEpoch;assert((await room.receipts(saved[0].messageId,options)).length===1,'explicit original HTTP token');await post('/revoke',{enrollment_id:session.offer.enrollment_id,operation_id:'revoke-http-'+cfg.suffix});let denied;try{await room.receipts(saved[0].messageId,options);}catch(error){denied=error;}assert(denied?.kind==='authentication'&&denied?.certainty==='refused','actual HTTP refuses revoked original token');await room.refresh(options);assert(client.transport.state==='connected'&&client.transport.physicalEpoch===epoch,'canonical control remains current after HTTP refusal');result.http_revoked_control_current++;}finally{client.close();}
 const mutations=trace.filter(v=>['conversation.create','message.send'].includes(v.request));assert(mutations.length===4&&new Set(mutations.map(v=>v.operation)).size===4,'four original canonical mutations with no resubmission');return {...result,canonical_mutations:mutations.length,synthetic_receipt_reports:2,credentials:6,devices:2,endpoints:6};
}catch(error){throw Error(String(error.stack??error)+'\n'+JSON.stringify(trace));}};
